const D = { density:.5, scale:1, hue:200, energy:.6, speed:1, x:.5, y:.5, spread:1, style:'prismatic', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI*2;
const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const MAXN = 150;

// ---- rebuild deterministic glint field on seed change ----
if (S.seedUsed !== P.seed || !S.sites) {
  S.seedUsed = P.seed;
  S.sites = [];
  for (let i = 0; i < MAXN; i++) {
    S.sites.push({
      bx: fr(i*3+1),
      by: fr(i*3+2),
      rate: 0.5 + fr(i*3+3)*3.4,          // twinkle speed
      ph: fr(i+11)*TAU,
      hj: (fr(i+29)-0.5)*70,              // hue jitter
      sz: 0.55 + fr(i+53)*0.9,            // size jitter
      arms: (fr(i+71) < 0.4) ? 4 : 6,     // spike count
      dr: 0.02 + fr(i+97)*0.05,           // drift rate
      da: 0.01 + fr(i+131)*0.03,          // drift amp (canvas frac)
      sh: 3 + fr(i+167)*5                 // twinkle sharpness
    });
  }
}

// ---- style ramps ----
const heat = b => { // thermal false-color: b 0..1 -> [h,s,v]
  if (b < .3) return [hw(P.hue-40), 90, 30 + b*120];
  if (b < .6) return [hw(28), 95, 55 + (b-.3)*130];
  if (b < .85) return [hw(52), 90, 92];
  return [hw(52), 22, 100];
};
const spectrum = [0, 45, 130, 195, 265, 315]; // rainbow arm offsets

const nActive = Math.round(Math.max(0, Math.min(1, P.density)) * MAXN);
const focusX = P.x, focusY = P.y;
const grow = 0.5 + P.spread*1.4;            // how far field spreads from focus
const beat = K.pulse * P.energy;            // beat pop
const sizeU = u * 0.05 * P.scale;

push();
blendMode(ADD);

for (let i = 0; i < nActive; i++) {
  const st = S.sites[i];
  // position: spread from focus, slow real-time drift (never rephases)
  const dxw = Math.sin(K.t*st.dr*P.speed + st.ph)*st.da;
  const dyw = Math.cos(K.t*st.dr*0.8*P.speed + st.ph*1.3)*st.da;
  const px = (focusX + (st.bx-0.5)*grow + dxw) * width;
  const py = (focusY + (st.by-0.5)*grow + dyw) * height;
  if (px < -sizeU || px > width+sizeU || py < -sizeU || py > height+sizeU) continue;

  // twinkle: continuous real-time baseline + audio + beat pop
  let tw = Math.pow(Math.max(0, Math.sin(K.t*st.rate*P.speed + st.ph)), st.sh);
  tw = tw*(0.35 + P.energy*0.65) + A.treble*0.7*fr(i+7) + beat*fr(i+3)*0.6;
  tw = Math.min(1.6, tw);
  if (tw < 0.04) continue;

  const sz = sizeU * st.sz * (0.35 + tw*0.75);
  const baseHue = hw(P.hue + st.hj);

  if (P.style === 'halftone') {
    // abstracted CMYK print rosette — ring of offset process dots
    const inks = [[190,80,95],[320,85,95],[52,90,100],[0,0,15]];
    noStroke();
    for (let k = 0; k < 4; k++) {
      const off = k*0.18;
      const ang = st.ph + k*1.1;
      const ox = Math.cos(ang)*sz*0.22, oy = Math.sin(ang)*sz*0.22;
      const c = inks[k];
      fill(c[0], c[1], c[2], 20 + tw*55);
      for (let d = 0; d < 6; d++) {
        const a2 = d/6*TAU + off;
        ellipse(px+ox+Math.cos(a2)*sz*0.32, py+oy+Math.sin(a2)*sz*0.32, sz*0.14, sz*0.14);
      }
    }
    continue;
  }

  // ---- diffraction spikes (prismatic / silver / thermal / ink) ----
  const arms = st.arms;
  noStroke();
  for (let a = 0; a < arms; a++) {
    const ang = a/arms*TAU + K.t*0.05*P.speed + st.ph*0.2;
    const len = sz * (a % 2 === 0 ? 1 : 0.55) * (0.8 + tw*0.6);
    const wdt = sz * 0.09 * (0.6 + tw*0.5);
    let h2, s2, v2;
    if (P.style === 'prismatic') { h2 = hw(baseHue + spectrum[a % 6]); s2 = 88; v2 = 100; }
    else if (P.style === 'silver') { h2 = hw(P.hue); s2 = 8; v2 = 100; }
    else if (P.style === 'thermal') { const c = heat(Math.min(1,tw)); h2 = c[0]; s2 = c[1]; v2 = c[2]; }
    else { h2 = hw(P.hue-10); s2 = 12; v2 = 92; } // ink: cold pale flecks
    const tipx = px + Math.cos(ang)*len, tipy = py + Math.sin(ang)*len;
    const pxn = Math.cos(ang+Math.PI/2)*wdt, pyn = Math.sin(ang+Math.PI/2)*wdt;
    fill(h2, s2, v2, 30 + tw*55);
    triangle(px+pxn, py+pyn, px-pxn, py-pyn, tipx, tipy);
  }
  // hot core
  if (P.style === 'thermal') { const c = heat(Math.min(1,tw*1.1)); fill(c[0], c[1]*0.4, 100, 40+tw*55); }
  else if (P.style === 'silver' || P.style === 'ink') fill(hw(P.hue), 6, 100, 45+tw*50);
  else fill(hw(baseHue+20), 25, 100, 45+tw*55);
  ellipse(px, py, sz*0.42*(0.6+tw*0.5), sz*0.42*(0.6+tw*0.5));
}

// ---- rare shooting glint that crosses frame (continuous, section-gated) ----
if (P.density > 0.05) {
  const period = 6.5;
  const idx = Math.floor(K.t / period);
  const fp = (K.t % period) / period;               // 0..1 progress
  if (fp < 0.5) {                                    // visible first half
    const r = fr(idx*13+1);
    const sy = fr(idx*13+2)*height;
    const dir = fr(idx*13+3) < 0.5 ? 1 : -1;
    const sx = (dir > 0 ? -0.1 + fp*2.4 : 1.1 - fp*2.4) * width;
    const tw = Math.sin(fp/0.5*Math.PI);
    const trail = u*0.16*P.scale;
    const hh = hw(P.style==='prismatic' ? P.hue + fp*300 : (P.style==='silver'||P.style==='ink'?P.hue:P.hue+30));
    const ss = (P.style==='silver'||P.style==='ink') ? 8 : 70;
    for (let t = 0; t < 6; t++) {
      const q = t/6;
      fill(hh, ss, 100, (18 + tw*45)*(1-q));
      noStroke();
      ellipse(sx - dir*trail*q, sy + q*trail*0.15, u*0.012*P.scale*(1-q*0.6), u*0.012*P.scale*(1-q*0.6));
    }
  }
}

blendMode(BLEND);
pop();
if (drawingContext) drawingContext.shadowBlur = 0;
